type RecordFields = {
  actorId: string;
  subjectKind: string;
  subjectId: string;
  projectId: string | null;
  summary: string;
  metadata: ActivityMetadata;
  occurredAt: Date | string | number;
};

function record(orgId: string, kind: string, event: RecordFields): Promise<void> {
  insertActivity({
    orgId,
    kind,
    actorId: event.actorId,
    subjectKind: event.subjectKind,
    subjectId: event.subjectId,
    projectId: event.projectId,
    summary: event.summary,
    metadata: event.metadata,
    occurredAt: event.occurredAt,
  });
  return Promise.resolve();
}

function actor(payload: ActivityPayload): string {
  if (!payload.actorId) {
    throw new Error("Activity entry requires the actor who performed the action");
  }
  return payload.actorId;
}

function projectId(payload: ActivityPayload): string | null {
  return payload.projectId ?? null;
}

function issueSubject(payload: ActivityPayload): string {
  const id = payload.issueId ?? payload.subjectId;
  if (!id) throw new Error("Activity entry requires an issue");
  return id;
}

function commentSubject(payload: ActivityPayload): string {
  const id = payload.commentId ?? payload.subjectId;
  if (!id) throw new Error("Activity entry requires a comment");
  return id;
}

function memberSubject(payload: ActivityPayload): string {
  const id = payload.memberId ?? payload.subjectId;
  if (!id) throw new Error("Activity entry requires a member");
  return id;
}

function merged(
  payload: ActivityPayload,
  base: ActivityMetadata,
): ActivityMetadata {
  return { ...base, ...(payload.metadata ?? {}) };
}

