let bound = false;

/** Subscribe once. A second call does not record the same action twice. */
export function ensureActivitySubscriptions(): void {
  if (bound) return;
  bound = true;
  for (const [type, handler] of HANDLERS) {
    subscribe(type, (payload) => handler(payload as ActivityPayload));
  }
}

ensureActivitySubscriptions();

export function loadActivityFeed(input: ListActivityInput) {
  return listActivity(input);
}

export type CatchUpEvent = {
  type: string;
  occurredAt: Date | string | number;
  payload: ActivityPayload;
};

/**
 * Write events that were missed at action time. The row keeps `occurredAt`
 * from the action, even though this job runs later.
 */
export async function catchUpActivity(events: CatchUpEvent[]): Promise<void> {
  ensureActivitySubscriptions();
  for (const event of events) {
    await publish(event.type, {
      ...event.payload,
      occurredAt: event.occurredAt,
    });
  }
}

import {
  ActivityRangeError,
  listActivity,
  type ActivityEvent,
} from "@/server/repositories/activity-repository";

export { ActivityRangeError };

export type ActivityExportFormat = "json" | "csv";

export type ActivityExportInput = {
  orgId: string;
  from?: Date | string | number;
  to?: Date | string | number;
  format?: ActivityExportFormat;
  projectId?: string;
};

export type ActivityExport = {
  format: ActivityExportFormat;
  entries: ActivityEvent[];
  body: string;
  contentType: string;
};

function csvCell(value: unknown): string {
  const text =
    value === null || value === undefined
      ? ""
      : value instanceof Date
        ? value.toISOString()
        : typeof value === "object"
          ? JSON.stringify(value)
          : String(value);
  if (/[",\n\r]/.test(text)) {
    return `"${text.replaceAll('"', '""')}"`;
  }
  return text;
}

function toCsv(entries: ActivityEvent[]): string {
  const header = [
    "id",
    "occurredAt",
    "orgId",
    "actorId",
    "kind",
    "subjectKind",
    "subjectId",
    "projectId",
    "summary",
    "details",
  ];
  const lines = [header.join(",")];
  for (const entry of entries) {
    lines.push(
      [
        entry.id,
        entry.occurredAt,
        entry.orgId,
        entry.actorId,
        entry.kind,
        entry.subjectKind,
        entry.subjectId,
        entry.projectId,
        entry.summary,
        entry.details,
      ]
        .map(csvCell)
        .join(","),
    );
  }
  return lines.join("\n");
}

/**
 * Every entry in the inclusive range, newest first, for this workspace only.
 * There is no page cap.
 */
export function exportActivity(input: ActivityExportInput): ActivityExport {
  const format = input.format ?? "json";
  const { items } = listActivity({
    orgId: input.orgId,
    projectId: input.projectId,
    since: input.from,
    until: input.to,
  });

  const seen = new Set<string>();
  const entries: ActivityEvent[] = [];
  for (const item of items) {
    if (item.orgId !== input.orgId) continue;
    if (seen.has(item.id)) continue;
    seen.add(item.id);
    entries.push(item);
  }
  entries.sort((a, b) => {
    const byTime = b.occurredAt.getTime() - a.occurredAt.getTime();
    if (byTime !== 0) return byTime;
    return a.id < b.id ? 1 : a.id > b.id ? -1 : 0;
  });

  if (format === "csv") {
    return {
      format,
      entries,
      body: toCsv(entries),
      contentType: "text/csv; charset=utf-8",
    };
  }

  const body = JSON.stringify(
    entries.map((entry) => ({
      id: entry.id,
      orgId: entry.orgId,
      actorId: entry.actorId,
      kind: entry.kind,
      subjectKind: entry.subjectKind,
      subjectId: entry.subjectId,
      projectId: entry.projectId,
      summary: entry.summary,
      metadata: entry.metadata,
      details: entry.details,
      occurredAt: entry.occurredAt.toISOString(),
    })),
  );
  return {
    format: "json",
    entries,
    body,
    contentType: "application/json; charset=utf-8",
  };
}

