export async function GET(request: Request) {
  const url = new URL(request.url);
  const orgId = workspaceId(request, url);
  if (!orgId) {
    return NextResponse.json({ error: "Workspace is required" }, { status: 400 });
  }

  const formatParam = url.searchParams.get("format") ?? "json";
  if (formatParam !== "json" && formatParam !== "csv") {
    return NextResponse.json({ error: "Format must be json or csv" }, { status: 400 });
  }
  const format = formatParam as ActivityExportFormat;
  const from = url.searchParams.get("from") ?? undefined;
  const to = url.searchParams.get("to") ?? undefined;
  const projectId = url.searchParams.get("projectId") ?? undefined;

  try {
    const result = exportActivity({ orgId, from, to, format, projectId });
    if (format === "csv") {
      return new NextResponse(result.body, {
        headers: { "content-type": result.contentType },
      });
    }
    return new NextResponse(result.body, {
      headers: { "content-type": result.contentType },
    });
  } catch (error) {
    if (error instanceof ActivityRangeError) {
      return NextResponse.json({ error: error.message }, { status: 400 });
    }
    throw error;
  }
