import { and, count, desc, eq, gte, inArray, lt, lte } from "drizzle-orm";
import { newId } from "@/lib/id";
import { activityEvents, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";

export class ActivityRangeError extends Error {
  constructor(message = "Time range ends before it starts") {
    super(message);
    this.name = "ActivityRangeError";
  }
}

export type ActivityMetadata = Record<string, unknown>;

export type ActivityEventInput = {
  orgId: string;
  actorId: string;
  kind: string;
  subjectKind: string;
  subjectId: string;
  projectId: string | null;
  summary: string;
  metadata: ActivityMetadata;
  /** When the action happened, not when this row is written. */
  occurredAt: Date | string | number;
};

export type ActivityEvent = {
  id: string;
  orgId: string;
  actorId: string;
  kind: string;
  subjectKind: string;
  subjectId: string;
  projectId: string | null;
  summary: string;
  metadata: ActivityMetadata;
  /** Same object as metadata. JSON export keeps this as the entry's details. */
  details: ActivityMetadata;
  occurredAt: Date;
};

export type ListActivityInput = {
  orgId: string;
  projectId?: string;
  since?: Date | string | number;
  until?: Date | string | number;
  kinds?: string[];
  /** Omit to return every matching row. Export depends on that. */
  limit?: number;
  offset?: number;
};

function coerceDate(value: Date | string | number, label: string): Date {
  const date = value instanceof Date ? new Date(value.getTime()) : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new ActivityRangeError(`${label} is not a valid time`);
  }
  return date;
}

export function assertInclusiveRange(
  since?: Date,
  until?: Date,
): void {
  if (since === undefined || until === undefined) return;
  if (until.getTime() < since.getTime()) {
    throw new ActivityRangeError();
  }
}

function parseMetadata(raw: unknown): ActivityMetadata {
  if (raw && typeof raw === "object") return raw as ActivityMetadata;
  if (typeof raw !== "string" || raw.length === 0) return {};
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed as ActivityMetadata;
    }
    return {};
  } catch {
    return {};
  }
}

function hydrate(row: typeof activityEvents.$inferSelect): ActivityEvent {
  const metadata = parseMetadata(row.metadata);
  return {
    id: row.id,
    orgId: row.orgId,
    actorId: row.actorId,
    kind: row.kind,
    subjectKind: row.subjectKind,
    subjectId: row.subjectId,
    projectId: row.projectId,
    summary: row.summary,
    metadata,
    details: metadata,
    occurredAt: coerceDate(row.occurredAt, "occurredAt"),
  };
}

export function insertActivity(event: ActivityEventInput): ActivityEvent {
  if (!event.orgId) {
    throw new Error("Activity entry requires a workspace");
  }
  if (!event.actorId) {
    throw new Error("Activity entry requires the actor who performed the action");
  }
  const occurredAt = coerceDate(event.occurredAt, "occurredAt");
  const db = getDb();
  const row = db
    .insert(activityEvents)
    .values({
      id: newId(),
      orgId: event.orgId,
      actorId: event.actorId,
      kind: event.kind,
      subjectKind: event.subjectKind,
      subjectId: event.subjectId,
      projectId: event.projectId,
      summary: event.summary,
      metadata: JSON.stringify(event.metadata),
      occurredAt,
    })
    .returning()
    .get();
  return hydrate(row);
}

export function listActivity(input: ListActivityInput): {
  total: number;
  items: ActivityEvent[];
} {
  if (!input.orgId) {
    throw new Error("Activity query requires a workspace");
  }
  const since =
    input.since === undefined ? undefined : coerceDate(input.since, "since");
  const until =
    input.until === undefined ? undefined : coerceDate(input.until, "until");
  assertInclusiveRange(since, until);

  if (input.kinds !== undefined && input.kinds.length === 0) {
    return { total: 0, items: [] };
  }

  const db = getDb();
  const filters = and(
    orgPredicate(activityEvents.orgId, input.orgId),
    input.projectId === undefined
      ? undefined
      : eq(activityEvents.projectId, input.projectId),
    since === undefined ? undefined : gte(activityEvents.occurredAt, since),
    // Both ends are included, so [T, T] returns the entries at that instant
    // and an entry that happened exactly at `until` stays in the range.
    until === undefined ? undefined : lte(activityEvents.occurredAt, until),
    input.kinds === undefined
      ? undefined
      : inArray(activityEvents.kind, input.kinds),
  );

  const total = db
    .select({ value: count() })
    .from(activityEvents)
    .where(filters)
    .get();

  const ordered = db
    .select()
    .from(activityEvents)
    .where(filters)
    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id));

  const rows =
    input.limit === undefined
      ? ordered.all()
      : ordered.limit(input.limit).offset(input.offset ?? 0).all();

  const items = rows.map(hydrate).filter((item) => item.orgId === input.orgId);
  return { total: Number(total?.value ?? 0), items };
}

/** Retention purge. Rows inside the window (`occurredAt >= cutoff`) stay. */
export function purgeActivityOlderThan(cutoff: Date): void {
  const db = getDb();
  db.delete(activityEvents)
    .where(lt(activityEvents.occurredAt, coerceDate(cutoff, "cutoff")))
    .run();
}
